	at := w.Offset
	end := at + 1
	if at < 0 || end < at {
		w.Overflow = true
		return true
	}
	if w.Measuring {
		w.Offset = end
		return true
	}
	if uint64(end) > uint64(len(w.Buffer)) {
		w.Overflow = true
		return true
	}
	w.Buffer[at] = uint8(v)
	w.Offset = end
	return true
