type IdWordBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *IdWordBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(IdWord{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	IdWordReset((*IdWord)(p))
	return true
}
func (b *IdWordBuilder) GetRoot() *IdWord {
	if b.Arena.Locked {
		return nil
	}
	return (*IdWord)(b.Arena.At(b.root))
}
func (b *IdWordBuilder) AsConst() *IdWord {
	if len(b.region) == 0 {
		return nil
	}
	return (*IdWord)(unsafe.Pointer(&b.region[0]))
}
func (b *IdWordBuilder) Region() []byte { return b.region }
func (b *IdWordBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), IdWordTableType(), &b.Arena)
}
func (b *IdWordBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), IdWordTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *IdWordBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), IdWordTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *IdWordBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// CardWordReset restores CardWord's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func CardWordReset(value *CardWord) {
	clear(value.S[:])
	value.SLength = 0
}

func CardWordMeasureBody(value *CardWord, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !CardWordSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func CardWordSaveBody(w *TableWriter, value *CardWord) bool {
	if !CardWordSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func CardWordSaveBodyFields(w *TableWriter, value *CardWord) bool {
	{
		if value.SLength < 0 || value.SLength > 515 {
			return false
		}
		if value.SLength > 0 {
			if ref := w.Ids.refAtHit(208, 0xaf63ee4c86020b22); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.SLength < 0 || value.SLength > 515 {
				return false
			}
			if !w.putLebPair(uint64(value.SLength)) {
				w.putLebWide(uint64(value.SLength))
			}
			w.Raw(value.S[:value.SLength])
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

