type UnitInstalledBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *UnitInstalledBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(UnitInstalled{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	UnitInstalledReset((*UnitInstalled)(p))
	return true
}
func (b *UnitInstalledBuilder) GetRoot() *UnitInstalled {
	if b.Arena.Locked {
		return nil
	}
	return (*UnitInstalled)(b.Arena.At(b.root))
}
func (b *UnitInstalledBuilder) AsConst() *UnitInstalled {
	if len(b.region) == 0 {
		return nil
	}
	return (*UnitInstalled)(unsafe.Pointer(&b.region[0]))
}
func (b *UnitInstalledBuilder) Region() []byte { return b.region }
func (b *UnitInstalledBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), UnitInstalledTableType(), &b.Arena)
}
func (b *UnitInstalledBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), UnitInstalledTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *UnitInstalledBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), UnitInstalledTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *UnitInstalledBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
