type HandoverBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *HandoverBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Handover{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	HandoverReset((*Handover)(p))
	return true
}
func (b *HandoverBuilder) GetRoot() *Handover {
	if b.Arena.Locked {
		return nil
	}
	return (*Handover)(b.Arena.At(b.root))
}
func (b *HandoverBuilder) AsConst() *Handover {
	if len(b.region) == 0 {
		return nil
	}
	return (*Handover)(unsafe.Pointer(&b.region[0]))
}
func (b *HandoverBuilder) Region() []byte { return b.region }
func (b *HandoverBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), HandoverTableType(), &b.Arena)
}
func (b *HandoverBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), HandoverTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *HandoverBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), HandoverTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *HandoverBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
