func SeatRecordLoadBuilder(b *SeatRecordBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, SeatRecordTableType(), SeatRecordTableType().NodeType, 0, report)
}

type SeatRecordBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *SeatRecordBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(SeatRecord{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	SeatRecordReset((*SeatRecord)(p))
	return true
}
func (b *SeatRecordBuilder) GetRoot() *SeatRecord {
	if b.Arena.Locked {
		return nil
	}
	return (*SeatRecord)(b.Arena.At(b.root))
}
func (b *SeatRecordBuilder) AsConst() *SeatRecord {
	if len(b.region) == 0 {
		return nil
	}
	return (*SeatRecord)(unsafe.Pointer(&b.region[0]))
}
func (b *SeatRecordBuilder) Region() []byte { return b.region }
func (b *SeatRecordBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), SeatRecordTableType(), &b.Arena)
}
func (b *SeatRecordBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), SeatRecordTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *SeatRecordBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), SeatRecordTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *SeatRecordBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// StoreLoginReset restores StoreLogin's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StoreLoginReset(value *StoreLogin) {
	clear(value.Redis[:])
	value.RedisLength = 0
	clear(value.User[:])
	value.UserLength = 0
	clear(value.Store[:])
	value.StoreLength = 0
	clear(value.As[:])
	value.AsLength = 0
	clear(value.Key[:])
	value.KeyLength = 0
	clear(value.Sops[:])
	value.SopsLength = 0
	clear(value.Secret[:])
	value.SecretLength = 0
}

