func (b *ShadowPartBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ShadowPart{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ShadowPartReset((*ShadowPart)(p))
	return true
}
func (b *ShadowPartBuilder) GetRoot() *ShadowPart {
	if b.Arena.Locked {
		return nil
	}
	return (*ShadowPart)(b.Arena.At(b.root))
}
func (b *ShadowPartBuilder) AsConst() *ShadowPart {
	if len(b.region) == 0 {
		return nil
	}
	return (*ShadowPart)(unsafe.Pointer(&b.region[0]))
}
func (b *ShadowPartBuilder) Region() []byte { return b.region }
func (b *ShadowPartBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ShadowPartTableType(), &b.Arena)
}
func (b *ShadowPartBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ShadowPartTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ShadowPartBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ShadowPartTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ShadowPartBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// ShadowPlanReset restores ShadowPlan's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ShadowPlanReset(value *ShadowPlan) {
	value.Epoch = 0
	clear(value.State[:])
	value.StateLength = 0
	value.Parts = TableList[ShadowPartRow]{}
	value.Size = 0
	value.TookNs = 0
	value.Reads = TableList[TextWordRow]{}
}

