type ShadowPlanBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ShadowPlanBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ShadowPlan{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ShadowPlanReset((*ShadowPlan)(p))
	return true
}
func (b *ShadowPlanBuilder) GetRoot() *ShadowPlan {
	if b.Arena.Locked {
		return nil
	}
	return (*ShadowPlan)(b.Arena.At(b.root))
}
func (b *ShadowPlanBuilder) AsConst() *ShadowPlan {
	if len(b.region) == 0 {
		return nil
	}
	return (*ShadowPlan)(unsafe.Pointer(&b.region[0]))
}
func (b *ShadowPlanBuilder) Region() []byte { return b.region }
func (b *ShadowPlanBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ShadowPlanTableType(), &b.Arena)
}
func (b *ShadowPlanBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ShadowPlanTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ShadowPlanBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ShadowPlanTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ShadowPlanBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
