// ShadowOutReset restores ShadowOut's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ShadowOutReset(value *ShadowOut) {
	ShadowPlanReset(&value.Shadow)
	value.ShadowPresent = false
	clear(value.Error[:])
	value.ErrorLength = 0
}

func ShadowOutMeasureBody(value *ShadowOut, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ShadowOutSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ShadowOutSaveBody(w *TableWriter, value *ShadowOut) bool {
	if !ShadowOutSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func ShadowOutSaveBodyFields(w *TableWriter, value *ShadowOut) bool {
	if value.ShadowPresent {
		{
			mark := w.Ids.Count
			ref := w.Ids.refAtHit(90, 0x48996f6e7b2a8a21)
			start := w.Ids.Count
			n := ShadowPlanMeasureBody(&value.Shadow, w.Ids)
			if n < 0 || w.Ids.Overflow {
				return false
			}
			if true {
				if w.Measuring {
					w.Advance(tableLebBytes(ref) + 1 + tableLebBytes(uint64(n)) + n)
				} else {
					w.Ids.Truncate(start)
					if !w.headerPair(ref, 13) {
						w.headerRest(ref, 13)
					}
					if !w.putLebPair(uint64(n)) {
						w.putLebWide(uint64(n))
					}
					if !ShadowPlanSaveBody(w, &value.Shadow) {
						return false
					}
				}
			} else {
				w.Ids.Truncate(mark)
			}
		}
	}
	{
		if value.ErrorLength < 0 || value.ErrorLength > 4096 {
			return false
		}
		if value.ErrorLength > 0 {
			if ref := w.Ids.refAtHit(188, 0x9f7452dd75d54d31); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.ErrorLength < 0 || value.ErrorLength > 4096 {
				return false
			}
			if !w.putLebPair(uint64(value.ErrorLength)) {
				w.putLebWide(uint64(value.ErrorLength))
			}
			w.Raw(value.Error[:value.ErrorLength])
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func ShadowOutLoadBody(r *TableReader, value *ShadowOut) bool {
	ShadowOutReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x48996f6e7b2a8a21: // shadow
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			ShadowPlanLoadBody(&sub, &value.Shadow)
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				ShadowPlanReset(&value.Shadow)
			}
			value.ShadowPresent = true
		case 0x9f7452dd75d54d31: // error
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Error[:])
				value.ErrorLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 4096 {
				keep = tableUtf8Clamp(sub.Buffer, 4096)
				r.Report.Clamped++
			}
			clear(value.Error[:])
			copy(value.Error[:keep], sub.Buffer)
			value.ErrorLength = int32(keep)
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

