func (b *LaneQuietBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(LaneQuiet{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LaneQuietReset((*LaneQuiet)(p))
	return true
}
func (b *LaneQuietBuilder) GetRoot() *LaneQuiet {
	if b.Arena.Locked {
		return nil
	}
	return (*LaneQuiet)(b.Arena.At(b.root))
}
