type ArchiveResultBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ArchiveResultBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ArchiveResult{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ArchiveResultReset((*ArchiveResult)(p))
	return true
}
func (b *ArchiveResultBuilder) GetRoot() *ArchiveResult {
	if b.Arena.Locked {
		return nil
	}
	return (*ArchiveResult)(b.Arena.At(b.root))
}
func (b *ArchiveResultBuilder) AsConst() *ArchiveResult {
	if len(b.region) == 0 {
		return nil
	}
	return (*ArchiveResult)(unsafe.Pointer(&b.region[0]))
}
func (b *ArchiveResultBuilder) Region() []byte { return b.region }
func (b *ArchiveResultBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ArchiveResultTableType(), &b.Arena)
}
func (b *ArchiveResultBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ArchiveResultTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ArchiveResultBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ArchiveResultTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ArchiveResultBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
