// PartTimeReset restores PartTime's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func PartTimeReset(value *PartTime) {
	clear(value.Table[:])
	value.TableLength = 0
	clear(value.Name[:])
	value.NameLength = 0
	value.TookNs = 0
	value.Trips = 0
	value.Reads = 0
	value.Rows = 0
	value.Stale = 0
	value.Mismatch = 0
	value.Asked = 0
	value.Refused = 0
	value.Lost = 0
}

func PartTimeMeasureBody(value *PartTime, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !PartTimeSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func PartTimeSaveBody(w *TableWriter, value *PartTime) bool {
	if !PartTimeSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
