func PartTimeLoadBuilder(b *PartTimeBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, PartTimeTableType(), PartTimeTableType().NodeType, 0, report)
}

type PartTimeBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *PartTimeBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(PartTime{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	PartTimeReset((*PartTime)(p))
	return true
}
func (b *PartTimeBuilder) GetRoot() *PartTime {
	if b.Arena.Locked {
		return nil
	}
	return (*PartTime)(b.Arena.At(b.root))
}
func (b *PartTimeBuilder) AsConst() *PartTime {
	if len(b.region) == 0 {
		return nil
	}
	return (*PartTime)(unsafe.Pointer(&b.region[0]))
}
func (b *PartTimeBuilder) Region() []byte { return b.region }
func (b *PartTimeBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), PartTimeTableType(), &b.Arena)
}
func (b *PartTimeBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), PartTimeTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *PartTimeBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), PartTimeTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *PartTimeBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

