	clear(value.Hint[:])
	value.HintLength = 0
	ArchiveResultReset(&value.Archive)
	value.ArchivePresent = false
	value.Order = TableList[IdWordRow]{}
	value.Times = TableList[PartTimeRow]{}
	value.TookNs = 0
	value.BusyRetries = 0
	value.RouteTrips = 0
	value.Said = TableList[TextWordRow]{}
