func (b *RemindViewBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(RemindView{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	RemindViewReset((*RemindView)(p))
	return true
}
func (b *RemindViewBuilder) GetRoot() *RemindView {
	if b.Arena.Locked {
		return nil
	}
	return (*RemindView)(b.Arena.At(b.root))
}
func (b *RemindViewBuilder) AsConst() *RemindView {
	if len(b.region) == 0 {
		return nil
	}
	return (*RemindView)(unsafe.Pointer(&b.region[0]))
}
func (b *RemindViewBuilder) Region() []byte { return b.region }
