func MeasureLoadBuilder(b *MeasureBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, MeasureTableType(), MeasureTableType().NodeType, 0, report)
}

type MeasureBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *MeasureBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Measure{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	MeasureReset((*Measure)(p))
	return true
}
func (b *MeasureBuilder) GetRoot() *Measure {
	if b.Arena.Locked {
		return nil
	}
	return (*Measure)(b.Arena.At(b.root))
}
func (b *MeasureBuilder) AsConst() *Measure {
	if len(b.region) == 0 {
		return nil
	}
	return (*Measure)(unsafe.Pointer(&b.region[0]))
}
func (b *MeasureBuilder) Region() []byte { return b.region }
func (b *MeasureBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), MeasureTableType(), &b.Arena)
}
func (b *MeasureBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), MeasureTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *MeasureBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), MeasureTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *MeasureBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

